output_text:
[
  {
    "id": "must_take_entry_cart",
    "text": "A shopper must take the cart from the entrance cart station before continuing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": "at(1,5)"
      },
      "events": {
        "take_entry_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entry_cart"
    }
  },
  {
    "id": "must_return_cart_northwest",
    "text": "Any cart that is taken must eventually be returned to the northwest cart-return area before the shopper exits.",
    "abstraction": {
      "state_properties": {
        "northwest_cart_return": "at(0,1)",
        "cart_parked_northwest": "cartAt(0,1)"
      },
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_northwest": {
          "pre": {
            "and": [
              "northwest_cart_return",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_northwest"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_northwest"
    }
  },
  {
    "id": "no_abandon_cart_elsewhere",
    "text": "A shopper is forbidden from leaving a cart anywhere except the designated northwest cart-return area.",
    "abstraction": {
      "state_properties": {
        "northwest_cart_return": "at(0,1)"
      },
      "events": {
        "leave_cart_outside_return": {
          "pre": {
            "and": [
              "LEAVE_CART",
              {
                "not": "northwest_cart_return"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_return"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "A shopper may not leave the store while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "possessing_cart": "hasCart",
        "exit_cell": "at(9,5)"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "EXIT",
              "possessing_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "no_carts_in_exit_lane",
    "text": "Shopping carts are not allowed in the bottom exit lane beyond the cart station.",
    "abstraction": {
      "state_properties": {
        "bottom_exit_lane": {
          "or": [
            "at(2,5)",
            "at(3,5)",
            "at(4,5)",
            "at(5,5)",
            "at(6,5)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "cart_in_exit_lane": {
          "and": [
            "hasCart",
            "bottom_exit_lane"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_exit_lane"
    }
  },
  {
    "id": "no_hand_carrying_goods",
    "text": "Goods must not be carried loose by hand; item pickup is allowed only when the shopper has a cart.",
    "abstraction": {
      "state_properties": {
        "hands_full": "handFull"
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "hands_full",
          "pickup_item_without_cart"
        ]
      }
    }
  },
  {
    "id": "pickup_only_at_product_bays",
    "text": "Items may be picked up only at designated product bays, including the newly distinguished shelf position at cell (3,2).",
    "abstraction": {
      "state_properties": {
        "product_bay": {
          "or": [
            "at(2,2)",
            "at(3,2)",
            "at(5,2)",
            "at(6,2)"
          ]
        }
      },
      "events": {
        "illegal_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "product_bay"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "illegal_item_pickup"
    }
  },
  {
    "id": "must_reenter_checkout_from_start",
    "text": "After returning the cart, the shopper must approach checkout through the entrance-side bottom cell before exiting.",
    "abstraction": {
      "state_properties": {
        "northwest_cart_return": "at(0,1)",
        "cart_parked_northwest": "cartAt(0,1)",
        "checkout_approach": "at(0,5)"
      },
      "events": {
        "return_cart_northwest": {
          "pre": {
            "and": [
              "northwest_cart_return",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_northwest"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "return_cart_northwest",
      "discharge": "checkout_approach"
    }
  }
]
